from scipy.optimize import least_squares
def build2(w):
    c=np.cos(w*t); s=np.sin(w*t)
    cols=[np.ones_like(t),x,v,v*v,v**3,c,s,v*c,v*s,t*c,t*s,t*v*c,t*v*s,t,t*t]
    return np.column_stack(cols)
def res2(p):
    X=build2(p[0])
    b,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return dv_dt-X@b
best=None
for w0 in np.linspace(0.3,0.6,31):
