from scipy.optimize import least_squares
def model(p):
    w=p[0]
    P=p[1]+p[2]*v+p[3]*v*v+p[4]*v**3
    R=p[5]+p[6]*v+p[7]*v*v
    th=p[8]+p[9]*v
    return P+R*np.cos(w*t-th)
def resm(p):
    return dv_dt-model(p)
best=None
for w0 in [0.3132,0.3132*1.01,0.31]:
    p0=[w0,3.7,-5.6,1.8,-0.2,6.5,0,0,0,0]
    r=least_squares(resm,p0,xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=5000)
    e=np.mean(r.fun**2)/np.var(dv_dt)
    if best is None or e<best[0]: best=(e,r.x)
